#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long k;
    cin >> n >> k;

    vector<long long> fact(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    vector<int> digits;
    for (int i = 1; i <= n; i++) digits.push_back(i);
    k--;
    for (int i = n; i >= 1; i--) {
        long long f = fact[i - 1];
        int idx = k / f;
        cout << digits[idx] << (i > 1 ? " " : "\n");
        digits.erase(digits.begin() + idx);
        k %= f;
    }

    return 0;
}

